import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.vLhlLNVn.js";const o="/assets/einstellungen-geraet-loeschen.B1to6Vda.png",n="/assets/konfig-manager-geraet-loeschen.OlNjjjn_.png",d="data:image/svg+xml;base64,",m=JSON.parse('{"title":"Managing devices","description":"","frontmatter":{"order":5,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/en/02.anleitungen/05.geraete-verwalten.md"},"headers":[],"relativePath":"adapter/wled/anleitungen/geraete-verwalten.md","filePath":"adapter/wled/anleitungen/geraete-verwalten.md","lastUpdated":null}'),h={name:"adapter/wled/anleitungen/geraete-verwalten.md"};function l(r,e,c,g,I,p){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="managing-devices" tabindex="-1">Managing devices <a class="header-anchor" href="#managing-devices" aria-label="Permalink to &quot;Managing devices&quot;">​</a></h1><p><a id="remove-wled-device-adapter"></a></p><h2 id="how-do-i-remove-a-wled-device-from-the-adapter" tabindex="-1">How do I remove a WLED device from the adapter? <a class="header-anchor" href="#how-do-i-remove-a-wled-device-from-the-adapter" aria-label="Permalink to &quot;How do I remove a WLED device from the adapter?&quot;">​</a></h2><p><strong>In short:</strong> You delete a device in the instance settings with the trash can icon on its card, or in the Admin&#39;s device manager. The adapter then removes all states of the device and stops its connection and timers. Nothing changes on the WLED device itself. If the device is still running in your network, the adapter finds it again via Bonjour and creates it anew. <strong>From v0.10.0</strong> you can switch off the automatic search, and then it stays gone.</p><h3 id="how-to-do-it-in-the-instance-settings" tabindex="-1">How to do it: in the instance settings <a class="header-anchor" href="#how-to-do-it-in-the-instance-settings" aria-label="Permalink to &quot;How to do it: in the instance settings&quot;">​</a></h3><p><strong>From v0.10.0:</strong> The instance settings show every device as a card with online status, IP address and firmware (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><ol><li>In Admin, open the settings of <code>wled.&lt;instance&gt;</code> under &quot;Instances&quot;. The &quot;Devices&quot; tab is already open.</li><li>On the device&#39;s card, click the trash can icon at the bottom right (&quot;Delete device&quot;).</li><li>The dialog asks &quot;Delete &lt;device&gt;?&quot; and explains: &quot;The device and all its states are removed from ioBroker. Nothing changes on the WLED device itself.&quot; Click &quot;Delete&quot;.</li><li>&quot;&lt;device&gt; was deleted.&quot; appears at the bottom and the card disappears. If the device no longer exists, the dialog shows &quot;&lt;device&gt; does not exist any more.&quot;; for any other error it shows &quot;That did not work. See the instance log for details.&quot;</li></ol><p><img src="'+o+'" alt="Instance settings of wled.0, &quot;Devices&quot; tab: on top of the device cards is the dialog &quot;Delete Balcony?&quot; with the buttons &quot;Cancel&quot; and &quot;Delete&quot;."></p><p>You delete a device that is offline in the same way. The instance has to be running for this. If it is stopped, the tab shows &quot;The instance is not running&quot; and a &quot;Start instance&quot; button.</p><h3 id="how-to-do-it-in-the-device-manager" tabindex="-1">How to do it: in the device manager <a class="header-anchor" href="#how-to-do-it-in-the-device-manager" aria-label="Permalink to &quot;How to do it: in the device manager&quot;">​</a></h3><p>The device manager is the Admin&#39;s device overview. In Admin 8.3 the tab is called &quot;Config manager&quot;; in older Admin versions it is &quot;Devices&quot;.</p><ol><li>In Admin, open the &quot;Config manager&quot; tab (or &quot;Devices&quot;) and select the instance <code>wled.&lt;instance&gt;</code>.</li><li>On the device&#39;s card, click the trash can icon (&quot;Delete this device&quot;).</li><li>Confirm the question &quot;Do you really want to delete the device &lt;MAC&gt;?&quot; with &quot;Yes&quot;. The question names the MAC address from the object ID, not the name.</li><li>The device disappears from the list. The log shows <code>&lt;MAC&gt; deleted</code>. If deleting fails, &quot;Can not delete device &lt;device&gt;&quot; appears.</li></ol><p><strong>From v0.10.1:</strong> The question names the device and adds the MAC in brackets: &quot;Do you really want to delete the device &lt;device&gt; (&lt;MAC&gt;)?&quot;. If the device has no name of its own, only the MAC appears (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/965" target="_blank" rel="noreferrer">#965</a>).</p><p><img src="'+n+'" alt="Device manager in Admin 8.3 (&quot;Config manager&quot; tab) with the cards of the WLED devices of wled.0 and the confirmation &quot;Do you really want to delete the device MAC?&quot; with &quot;Yes&quot; and &quot;No&quot;."></p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>When deleting, the adapter removes the device object <code>wled.&lt;instance&gt;.&lt;MAC&gt;</code> with all states below it. Scripts, VIS views and aliases that point to these states will then point to nothing. If the adapter creates the device again later, the states are recreated under the same MAC.</p></div><h3 id="what-the-adapter-cleans-up-when-you-delete-a-device" tabindex="-1">What the adapter cleans up when you delete a device <a class="header-anchor" href="#what-the-adapter-cleans-up-when-you-delete-a-device" aria-label="Permalink to &quot;What the adapter cleans up when you delete a device&quot;">​</a></h3><p>For that device, the adapter stops the watchdog and the timers, closes the WebSocket connection and forgets the device. This also happens if you delete the device object <code>wled.&lt;instance&gt;.&lt;MAC&gt;</code> directly in the &quot;Objects&quot; tab. The log then shows <code>Device &lt;MAC&gt; was deleted from object tree, cleaning up backend processes and objects</code>.</p><p>If the adapter doesn&#39;t know the device when you delete it in the &quot;Objects&quot; tab, for example because it was never connected, it reports <code>Device &lt;MAC&gt; not found in devices array, cannot clean up backend processes and objects</code>. The objects are deleted anyway; you can ignore the warning.</p><h3 id="why-does-the-deleted-device-come-back" tabindex="-1">Why does the deleted device come back? <a class="header-anchor" href="#why-does-the-deleted-device-come-back" aria-label="Permalink to &quot;Why does the deleted device come back?&quot;">​</a></h3><p>The adapter looks for WLED devices via Bonjour (mDNS). The search starts when the adapter starts and when you click &quot;Search devices&quot; in the instance settings or &quot;Discover new devices&quot; in the device manager. After that it keeps listening until the instance stops. If a device the adapter doesn&#39;t know answers, the adapter creates it anew. A deleted device that is still switched on in your network therefore reappears. There is no list that lets you exclude individual devices from the search.</p><p>So only delete a device once you no longer use it or have taken it off the network.</p><p><strong>From v0.10.0:</strong> In the instance settings, on the &quot;Settings&quot; tab under &quot;Discovery&quot;, switch off &quot;Search devices automatically via Bonjour/mDNS&quot; (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/897" target="_blank" rel="noreferrer">#897</a>). The adapter then no longer searches on start and only uses the devices it already knows or that you add by IP. A deleted device stays gone. If you start the search by hand (&quot;Search devices&quot;), it listens until the next restart of the instance and finds the device again.</p><p><img src="'+d+'" alt="Flow: You delete the device in the &quot;Devices&quot; tab, in the instance settings, in the &quot;Objects&quot; tab or from a script. The adapter deletes the states and stops the watchdog, timers and WebSocket. If the device is still running in the network, Bonjour finds it again when the adapter starts or on &quot;Discover new devices&quot;, and the adapter creates it anew under the same MAC."></p><h3 id="delete-a-device-from-a-script" tabindex="-1">Delete a device from a script <a class="header-anchor" href="#delete-a-device-from-a-script" aria-label="Permalink to &quot;Delete a device from a script&quot;">​</a></h3><p>With <code>sendTo</code> you delete a device by its IP address. The answer is <code>success</code> or <code>failed</code>:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;deleteDevice&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;192.168.x.y&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Delete device: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>If the adapter can&#39;t find a device with this IP address, the log shows <code>Device with IP 192.168.x.y not found</code> and the answer is <code>failed</code>.</p><p><strong>From v0.10.0:</strong> You can also delete the device by its MAC address, as it appears in the object ID. The answer is then an object: <code>{ ok: true }</code> or, for example, <code>{ ok: false, error: &#39;notFound&#39; }</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;deleteDevice&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;MAC&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Delete device: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ok</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;deleted&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">error</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><h3 id="older-versions" tabindex="-1">Older versions <a class="header-anchor" href="#older-versions" aria-label="Permalink to &quot;Older versions&quot;">​</a></h3><p><strong>Up to v0.9.3:</strong> The instance settings show a device table. To delete, click the red button with the trash can icon in the &quot;Remove&quot; column. The dialog &quot;Delete device confirmation&quot; shows the name and IP address; confirm with &quot;Delete Device&quot;. Afterwards &quot;Device deleted successfully&quot; or &quot;Failed to delete device&quot; appears.</p><p><strong>Up to v0.9.2:</strong> In the instance settings you can&#39;t delete a device that has been offline since the adapter started. &quot;Failed to delete device&quot; appears, and the log shows <code>Device with IP 192.168.x.y not found</code>. In that case, delete the device in the device manager or in the &quot;Objects&quot; tab.</p><p><strong>From v0.9.3:</strong> Deleting in the instance settings also works for devices that are offline (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/787" target="_blank" rel="noreferrer">#787</a>). For this, the adapter also looks for the device in the object tree.</p><p><strong>Up to v0.9.2:</strong> In the device manager, the dialog doesn&#39;t wait for the result and doesn&#39;t show an error. For instances from <code>wled.10</code> upwards, deleting fails there. Use the &quot;Objects&quot; tab instead.</p><p><strong>From v0.9.3:</strong> The dialog in the device manager waits for the result, shows &quot;Can not delete device &lt;device&gt;&quot; if something goes wrong, and also works for instances from <code>wled.10</code> upwards (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/914" target="_blank" rel="noreferrer">#914</a>).</p><p><strong>From v0.9.3:</strong> &quot;Discover new devices&quot; first stops the running search and then starts a new one. Searches no longer run side by side (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/905" target="_blank" rel="noreferrer">#905</a>).</p><p><strong>See also:</strong> <a href="./../erste-schritte/erstes-geraet#adapter-wled-devices-automatically">How and when does the adapter find my WLED devices automatically?</a> · <a href="./../erste-schritte/erstes-geraet#add-device-manually-ip-if">How do I add a device manually by IP?</a></p><p><a id="deal-switched-off-offline-devices"></a></p><h2 id="how-do-i-deal-with-devices-that-are-switched-off-or-offline-and-how-do-i-get-rid-of-the-log-messages" tabindex="-1">How do I deal with devices that are switched off or offline, and how do I get rid of the log messages? <a class="header-anchor" href="#how-do-i-deal-with-devices-that-are-switched-off-or-offline-and-how-do-i-get-rid-of-the-log-messages" aria-label="Permalink to &quot;How do I deal with devices that are switched off or offline, and how do I get rid of the log messages?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="happens-commands-sent-switched-off"></a></p><h2 id="what-happens-to-commands-sent-to-a-device-that-is-switched-off" tabindex="-1">What happens to commands sent to a device that is switched off? <a class="header-anchor" href="#what-happens-to-commands-sent-to-a-device-that-is-switched-off" aria-label="Permalink to &quot;What happens to commands sent to a device that is switched off?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',43)])])}const k=t(h,[["render",l]]);export{m as __pageData,k as default};
